package com.glassstorm.phonemanager.ui

import androidx.compose.foundation.isSystemInDarkTheme
import androidx.compose.foundation.text.selection.LocalTextSelectionColors
import androidx.compose.runtime.Composable
import androidx.compose.runtime.CompositionLocalProvider
import androidx.compose.ui.graphics.Color

/**
 * The hub's visual theme: a calm, bright, assistant palette layered ON TOP of the
 * generated Lumo kit.
 *
 * The design system under `ui/` (`Theme.kt`, `Color.kt`, `Typography.kt`, and the
 * `ui/components` and `ui/foundation` trees) is GENERATED by the Lumo plugin and
 * must not be hand-edited. Its default palette is a neutral Swiss scheme (primary =
 * black, surface = grey). Rather than edit generated code, this file wraps
 * [AppTheme] and re-provides [LocalColors] with the hub palette; every kit
 * component (`Button`, `Card`, `Surface`, `Text`, text fields) reads
 * `AppTheme.colors` and so adopts the new palette automatically.
 *
 * The selection colours and the ambient content colour are re-provided too, so the
 * caret and default text colour follow this palette rather than the kit default.
 *
 * All pairs are held to WCAG 2.1 AA and are verified by `HubPaletteContrastTest` —
 * the numbers are asserted, not eyeballed. See `DESIGN.md` for the table.
 */
@Composable
fun HubTheme(
    isDarkTheme: Boolean = isSystemInDarkTheme(),
    content: @Composable () -> Unit,
) {
    AppTheme(isDarkTheme = isDarkTheme) {
        val hubColors = if (isDarkTheme) HubDarkColors else HubLightColors
        CompositionLocalProvider(
            LocalColors provides hubColors,
            LocalTextSelectionColors provides rememberTextSelectionColors(hubColors),
            LocalContentColor provides hubColors.contentColorFor(hubColors.background),
            content = content,
        )
    }
}

// --- Light palette ---------------------------------------------------------

private val HubLightBackground = Color(0xFFEEF4F9)
private val HubLightSurface = Color(0xFFFFFFFF)
private val HubLightInk = Color(0xFF0F1A24)
private val HubLightInkSecondary = Color(0xFF4A5A68)
private val HubLightInkDisabled = Color(0xFF8A97A3)
private val HubLightPrimary = Color(0xFF0E6FBA)
private val HubLightSecondary = Color(0xFF33475B)
private val HubLightTertiary = Color(0xFF29ABE2)
private val HubLightOnTertiary = Color(0xFF05293D)
private val HubLightSuccess = Color(0xFF1B7A46)
private val HubLightError = Color(0xFFB3261E)
private val HubLightDisabled = Color(0xFFE3EAF1)
private val HubLightOnDisabled = Color(0xFF6B7A88)
private val HubLightOutline = Color(0xFF7C8C9B)

internal val HubLightColors: Colors =
    Colors(
        primary = HubLightPrimary,
        onPrimary = Color.White,
        secondary = HubLightSecondary,
        onSecondary = Color.White,
        tertiary = HubLightTertiary,
        onTertiary = HubLightOnTertiary,
        error = HubLightError,
        onError = Color.White,
        success = HubLightSuccess,
        onSuccess = Color.White,
        disabled = HubLightDisabled,
        onDisabled = HubLightOnDisabled,
        surface = HubLightSurface,
        onSurface = HubLightInk,
        background = HubLightBackground,
        onBackground = HubLightInk,
        outline = HubLightOutline,
        text = HubLightInk,
        textSecondary = HubLightInkSecondary,
        textDisabled = HubLightInkDisabled,
        scrim = Color.Black.copy(alpha = 0.32f),
        elevation = HubLightSecondary,
    )

